package br.com.balancecontrol.order.dto;

import br.com.balancecontrol.order.OrderOrigin;
import java.util.List;
import java.util.UUID;
import javax.validation.Valid;
import javax.validation.constraints.NotBlank;
import javax.validation.constraints.NotEmpty;
import javax.validation.constraints.NotNull;
import javax.validation.constraints.Size;

/**
 * {@code externalId} is the idempotency key (R6), generated by the client once per order:
 * the integration sends its own id; the portal generates a UUID when the form is opened, so
 * a double click or a retry after a timeout also cannot create a second order.
 */
public record PlaceOrderRequest(
        @NotNull UUID externalId,
        @NotBlank @Size(max = 20) String agencyCode,
        @NotBlank @Size(max = 100) String requester,
        @NotNull OrderOrigin origin,
        @NotEmpty @Size(max = 200) List<@Valid @NotNull OrderLineRequest> items) {
}
